SINA_SMART["histo1-connective"] = {"lecture":"histo1-connective","title":"Connective tissue","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"histo1-connective:e0","text":"CT ≈ 50% of body weight; cells + ECM (fibres, ground substance, fluid).","topic":"Overview and classification","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-connective:e1","text":"All CT from mesenchyme; vascular except cartilage.","topic":"Overview and classification","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-connective:e2","text":"Classes: CT proper, CT with special properties, supporting CT.","topic":"Overview and classification","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-connective:e3","text":"Fibroblast: makes fibres and ground substance; fibrocyte = inactive.","topic":"Cells of connective tissue","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-connective:e4","text":"Mast cell: histamine + heparin, IgE receptors, allergy.","topic":"Cells of connective tissue","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-connective:e5","text":"Macrophage from monocyte; plasma cell from B cell, clock-face nucleus.","topic":"Cells of connective tissue","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-connective:e6","text":"Collagen I strongest; hydroxylation needs vitamin C; procollagen → tropocollagen outside the cell.","topic":"Fibres","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-connective:e7","text":"Reticular fibres = type III, silver-stained; elastic fibres = elastin + fibrillin.","topic":"Fibres","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-connective:e8","text":"Dense regular: tendons; dense irregular: dermis.","topic":"Types of connective tissue","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-connective:e9","text":"Mucous CT: Wharton's jelly; white vs brown fat.","topic":"Types of connective tissue","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"iacgof":"a","hm7szh":"a","175im2":"a","2qt2bw":"a","1hjj7zo":"a","rl8ep0":"a","1daj0zm":"a","pp351":"a","1liv0so":"a","gcz5m8":"a","153r6mm":"a","eoz35f":"a","1xk18cc":"a","1lt0pkh":"a","upwa1y":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"histo1-connective:e0":{"s":0,"u":["CT ≈ 50% of body weight; cells + ECM (fibres, ground substance, fluid).","It consists of cells embedded in an extracellular matrix (ECM) of fibres (collagen, reticular, elastic), ground substance and tissue fluid; the ECM's composition sets strength, elasticity and resilience.","Connective tissue (CT) is found everywhere, about 50% of body weight ."],"dp":[]},"histo1-connective:e1":{"s":0,"u":["All CT from mesenchyme; vascular except cartilage.","Cells are varied but few; the matrix predominates; CT is vascularised except cartilage .","All CT arises from mesenchyme , the embryonic CT derived mainly from mesoderm; mesenchymal stem cells persist in the bone marrow."],"dp":[]},"histo1-connective:e2":{"s":0,"u":["Classes: CT proper, CT with special properties, supporting CT.","Classification: CT proper (loose/areolar; dense regular or irregular), CT with special properties (adipose, elastic, haematopoietic, mucous), and supporting CT (cartilage, bone)."],"dp":[]},"histo1-connective:e3":{"s":1,"u":["Fibroblast: makes fibres and ground substance; fibrocyte = inactive.","Fibroblasts , the main cells, synthesise fibres and ground substance and the enzymes that break them down (collagenase, elastase); fibrocytes are the inactive form and can be reactivated.","Reticular cells (stellate) make reticular fibres in haematopoietic and lymphoid tissue, can phagocytose and present antigen."],"dp":[]},"histo1-connective:e4":{"s":1,"u":["Mast cell: histamine + heparin, IgE receptors, allergy.","Mast cells come from the bone marrow, carry basophilic granules of histamine and heparin and surface IgE receptors ; degranulation in allergy increases vascular permeability (oedema, itch), mucus and bronchoconstriction."],"dp":[]},"histo1-connective:e5":{"s":1,"u":["Macrophage from monocyte; plasma cell from B cell, clock-face nucleus.","Plasma cells come from antigen-stimulated B lymphocytes, secrete antibodies and have a clock-face nucleus .","Macrophages derive from blood monocytes , phagocytose debris and present antigen."],"dp":[]},"histo1-connective:e6":{"s":2,"u":["Collagen I strongest; hydroxylation needs vitamin C; procollagen → tropocollagen outside the cell.","Synthesis inside the fibroblast: translation of the α chains, hydroxylation of proline and lysine (needs vitamin C), glycosylation, assembly of three chains into procollagen , exocytosis.","Outside: procollagen peptidase removes the end peptides to give tropocollagen , which assembles into fibrils, then fibres."],"dp":[{"h":"Scurvy: when collagen cannot be finished","t":"Hydroxylation of proline and lysine is what lets collagen chains form a stable triple helix and cross-link. The enzymes need vitamin C . Without it, fibroblasts secrete weak collagen, so the tissues with the fastest collagen turnover fail first: gums swell and bleed, teeth loosen, small vessels rupture (bleeding around hair follicles, bruising) and wounds reopen. It is a direct clinical lesson in the collagen synthesis steps of this lecture, and it resolves within days of giving vitamin C. Source: the lecture's collagen synthesis; the Study Summary's deficiency hooks."}]},"histo1-connective:e7":{"s":2,"u":["Reticular fibres = type III, silver-stained; elastic fibres = elastin + fibrillin.","Reticular fibres : type III collagen , thin, forming delicate networks in liver, lymph nodes, spleen and haematopoietic organs and supporting capillaries, nerves and muscle fibres; they are stained by silver (argyrophilic).","Elastic fibres : elastin with microfibrils (fibrillin); less tensile than collagen but stretch and recoil; aorta, lungs, yellow ligaments (ligamenta flava)."],"dp":[]},"histo1-connective:e8":{"s":3,"u":["Dense regular: tendons; dense irregular: dermis.","Dense regular : parallel collagen bundles resisting pull in one direction (tendons, ligaments).","Dense irregular : interwoven collagen bundles resisting pull in all directions (dermis, organ capsules)."],"dp":[]},"histo1-connective:e9":{"s":3,"u":["Mucous CT: Wharton's jelly; white vs brown fat.","Mucous CT : few cells and fibres, abundant hyaluronan , jelly-like, cushioning: umbilical cord (Wharton's jelly) and the nucleus pulposus.","Adipose tissue : white fat (one large droplet, signet-ring nucleus; energy store, insulation) and brown fat (many small droplets, many mitochondria; heat production, prominent in newborns)."],"dp":[]}},"meta":{"iacgof":{"a":"recall","vg":"histo1-connective:e1/recall/1"},"hm7szh":{"a":"recall","vg":"histo1-connective:e1/recall/2"},"175im2":{"a":"recall","vg":"histo1-connective:e3/recall/1"},"2qt2bw":{"a":"recall","vg":"histo1-connective:e4/recall/1"},"1hjj7zo":{"a":"recall","vg":"histo1-connective:e5/recall/1"},"rl8ep0":{"a":"recall","vg":"histo1-connective:e5/recall/2"},"1daj0zm":{"a":"recall","vg":"histo1-connective:e7/recall/1"},"pp351":{"a":"recall","vg":"histo1-connective:e7/recall/1"},"1liv0so":{"a":"recall","vg":"histo1-connective:e6/recall/1"},"gcz5m8":{"a":"recall","vg":"histo1-connective:e6/recall/2"},"153r6mm":{"a":"recall","vg":"histo1-connective:e7/recall/2"},"eoz35f":{"a":"recall","vg":"histo1-connective:e8/recall/1"},"1xk18cc":{"a":"recall","vg":"histo1-connective:e8/recall/2"},"1lt0pkh":{"a":"recall","vg":"histo1-connective:e9/recall/1"},"upwa1y":{"a":"recall","vg":"histo1-connective:e9/recall/2"}},"explRev":"3c17e30824f0"};
